import test from 'node:test';import assert from 'node:assert/strict';
import {installChunkDeliveryProbe} from '../tools/experiments/qa-chunk-delivery-probe.js';
function fixture(){const loaded=new Map();return {epoch:0,stale:new Set(),loaded:()=>loaded,plan(desired,force){if(force)this.epoch++;this.desired=desired;},install(job,data){loaded.set(job.cx+','+job.cz,data);},prepareAsync:async data=>data,summary:()=>({failed:0})};}
test('delivery probe retains one demand across replans and separates prepare/install completion',async()=>{const s=fixture(),original=s.plan,finish=installChunkDeliveryProbe({chunkStream:s}),desired=new Map([['1,2',{cx:1,cz:2}]]);s.plan(desired);s.plan(desired);const data={cx:1,cz:2};assert.equal(await s.prepareAsync(data,()=>true),data);s.install({epoch:0,cx:1,cz:2},data);const report=finish();assert.equal(report.records.length,1);const row=report.records[0];assert(row.prepareStart>=row.demandAt);assert(row.prepareEnd>=row.prepareStart);assert(row.installedAt>=row.installStart);assert.equal(report.pending.length,0);assert.equal(s.plan,original);});
test('delivery probe preserves cancelled and unresolved demands across epoch changes',()=>{const s=fixture(),finish=installChunkDeliveryProbe({chunkStream:s}),desired=new Map([['1,2',{cx:1,cz:2}]]);s.plan(desired);s.plan(desired,true);const report=finish();assert.equal(report.records.length,2);assert(report.records[0].cancelledAt>=report.records[0].demandAt);assert.equal(report.pending.length,1);assert.equal(report.pending[0].epoch,1);});
test('delivery probe does not replace later owners when restored',()=>{const s=fixture(),finish=installChunkDeliveryProbe({chunkStream:s}),later=()=>{};s.plan=later;finish();assert.equal(s.plan,later);});
